def valid(number):
    """Return True if the card number passes the Luhn check."""
    digits = number.replace(" ", "")
    if len(digits) < 2 or not digits.isdigit():
        return False

    total = 0
    parity = len(digits) % 2
    for i, char in enumerate(digits):
        digit = int(char)
        if i % 2 == parity:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0

